const fs = require('node:fs');
const input = JSON.parse(fs.readFileSync(0, 'utf8'));
if (!Array.isArray(input.rows) || input.rows.length < 8 || input.rows.length > 10000) throw Error('Supply 8–10000 training/test rows');
const rows = input.rows;
if (rows.some(r => !Number.isFinite(r.x) || !Number.isFinite(r.y))) throw Error('Each row needs finite numeric x and y');
const split = Math.max(4, Math.min(rows.length - 2, Math.floor(rows.length * 0.7)));
const train=rows.slice(0,split), test=rows.slice(split);
const mean = (a) => a.reduce((s,v)=>s+v,0)/a.length;
const mx=mean(train.map(r=>r.x)), my=mean(train.map(r=>r.y));
const variance=train.reduce((s,r)=>s+(r.x-mx)**2,0);
if (!variance) throw Error('Training x values must vary');
const slope=train.reduce((s,r)=>s+(r.x-mx)*(r.y-my),0)/variance, intercept=my-slope*mx;
const predictions=test.map(r=>({x:r.x,actual:r.y,predicted:slope*r.x+intercept}));
const mae=mean(predictions.map(r=>Math.abs(r.actual-r.predicted)));
if (![slope,intercept,mae,...predictions.map(r=>r.predicted)].every(Number.isFinite)) throw Error("Numeric overflow; scale your dataset");
const model={format:'consilium-linear-regression',version:1,slope,intercept};
console.log(JSON.stringify({model,metrics:{mae,train_rows:train.length,test_rows:test.length,split:'ordered holdout'},predictions,blocks:[{kind:'heading',level:1,text:'Regression experiment'},{kind:'paragraph',text:'Held-out MAE: '+mae.toFixed(4)+'. Train: '+train.length+'; test: '+test.length+'. Ordered split; this example does not prove generalization to other datasets.'},{kind:'paragraph',text:JSON.stringify(model)}]}));
